def hex_to_decimal(hex_number):
    """
    Convert a hexadecimal number (as a string) to its decimal equivalent.

    Parameters:
    hex_number (str): The hexadecimal number to convert.

    Returns:
    float: The decimal equivalent of the hexadecimal number, or None if the input is invalid.
    """
    def char_to_value(c):
        if '0' <= c <= '9':
            return ord(c) - ord('0')
        elif 'A' <= c <= 'F':
            return ord(c) - ord('A') + 10
        elif 'a' <= c <= 'f':
            return ord(c) - ord('a') + 10
        else:
            raise ValueError(f"Invalid character in hexadecimal number: {c}")

    try:
        if '.' in hex_number:
            integer_part, fractional_part = hex_number.split('.')
        else:
            integer_part, fractional_part = hex_number, ''

        decimal_value = 0.0
        power = 0

        for c in reversed(integer_part):
            decimal_value += char_to_value(c) * (16 ** power)
            power += 1

        power = -1
        for c in fractional_part:
            decimal_value += char_to_value(c) * (16 ** power)
            power -= 1

        return decimal_value

    except ValueError:
        return None

